using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Partners;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/suppliers")]public sealed class SuppliersController(DadoRetailDbContext db):ControllerBase{[HttpGet,HasPermission(Permissions.ProductView)]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Set<Supplier>().AsNoTracking().OrderBy(x=>x.Name).ToListAsync(ct));[HttpPost,HasPermission(Permissions.PurchaseCreate)]public async Task<IActionResult>Create(CreateSupplierRequest r,CancellationToken ct){var s=new Supplier(r.Name,r.TaxId,r.Phone);db.Add(s);await db.SaveChangesAsync(ct);return Ok(s);}}public sealed record CreateSupplierRequest(string Name,string? TaxId,string? Phone);
